window.kbPageData["views/entry/k-ac67a052412bb19d"] = {"key":"entry/k-ac67a052412bb19d","state":{"route":"entry/k-ac67a052412bb19d"},"node":{"id":"k-ac67a052412bb19d","mode":"k","title":"农村集体经济组织非成员的特定权利","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["农村集体经济组织中作出贡献的非成员取得特定权利的条件和范围"],"qs":["江苏 2025 C类 行测#13"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"依照《农村集体经济组织法》第十五条，非成员长期在农村集体经济组织工作并对集体作出贡献，经成员大会全体成员四分之三以上同意，可以参与分配集体收益、享受组织提供的服务和福利，并享有法律法规和组织章程规定的其他权利。","review":{"definition":"依照《农村集体经济组织法》第十五条，非成员长期在农村集体经济组织工作并对集体作出贡献，经成员大会全体成员四分之三以上同意，可以参与分配集体收益、享受组织提供的服务和福利，并享有法律法规和组织章程规定的其他权利。","explanation":"四分之三以上的同意门槛以成员大会全体成员为基数。第十五条援引第十三条第七项、第九项和第十项，涵盖题中的①和③。②所涉宅基地使用权对应第六项，④所涉土地补偿费分配对应第八项，两项均在本条授权范围之外，因此选B。","references":[],"evidence":"经农村集体经济组织成员大会全体成员四分之三以上同意，可以享有本法第十三条","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2025 C类 行测#13":{"paper":"江苏 2025 C类 行测","n":13,"mod":"常识判断","src":["ffc394a1c160f331ec57.pdf",4],"asrc":["d1de3b437151c05b769e.pdf",6],"card":"2e4c0d019fa2355fc6ce978c","links":[{"id":"k-ac67a052412bb19d","role":"直接考查","why":"法定列举将权利范围限定为参与分配集体收益、享受组织提供的服务和福利，以及法律法规和组织章程规定的其他权利。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-ac67a052412bb19d":[["江苏 2025 C类 行测#13"]]}};
